    bgt  s5, t0, rc_fail
    la   a0, s_ok
    li   a7, 4
    ecall
    j    rc_out
rc_fail:
    addi s1, s1, 1
    la   a0, s_fail
    li   a7, 4
    ecall
rc_out:
    lw   ra, 0(sp)
    addi sp, sp, 4
