    bgeu t4, t5, p_bad
    sll  t5, t6, t4
    and  a1, t1, t5
    bnez a1, p_bad              # repeated cubie
    or   t1, t1, t5
    sb   t4, 0(t0)
    lbu  t4, 7(a0)
    addi t4, t4, -49
    li   t5, 3
    bgeu t4, t5, p_bad
    sb   t4, 7(t0)
    add  t2, t2, t4
    addi a0, a0, 1
    addi t0, t0, 1
    addi t3, t3, -1
    bnez t3, p_loop
    lbu  t4, 7(a0)              # a0 now points at byte 7, so this is byte 14
    bnez t4, p_bad
    li   t5, 3
p_mod:                          # sum <= 14: subtract until below 3
    bltu t2, t5, p_sum
    addi t2, t2, -3
    j    p_mod
p_sum:
    seqz a0, t2
    ret
p_bad:
    li   a0, 0
    ret

